_FAQS = [
[('Можно ли заказать кран по мощности теплообменника?', 'Для разгрузки нужны масса и габариты конкретной поставки. Тепловая мощность аппарата не определяет грузовое место.'), ('Подъём и кантовка — одна операция?', 'В документации Alfa Laval предусмотрены отдельные схемы. Необходимые операции согласуют по положению прибывающего аппарата и конечному результату.'), ('Кран занесёт аппарат в подвал?', 'Возможность подачи определяется по площадке и проёму. Дальнейшее перемещение внутри здания может потребовать отдельной такелажной бригады.'), ('Кто определяет положение патрубков?', 'Положение согласуют с принимающей монтажной организацией по проектному чертежу до завершения разгрузки.')],
[('Какой кран нужен для силоса?', 'Нужны монтажная масса узла, схема установки и план площадки. Одной высоты силоса недостаточно для подбора.'), ('Обязательно ли использовать два крана?', 'Количество машин определяют по технологии конкретного монтажа. Универсального решения для всех исполнений силосов нет.'), ('Что делать при поставке секциями?', 'Передайте упаковочную ведомость и последовательность сборки. Разгрузку секций и монтаж укрупнённых узлов описывают отдельно.'), ('Кто подтверждает готовность фундамента?', 'Ответственная сторона проекта совместно с монтажной организацией. Визуального впечатления о состоянии бетона недостаточно.')],
[('Объём бака подходит для выбора крана?', 'Нужны масса и размеры самого изделия, а также место стоянки и опускания. Литраж не заменяет эти данные.'), ('Можно поднимать ёмкость с водой?', 'Для рассмотренных вертикальных баков Enduramaxx допускается подъём только пустого изделия. Для другой модели проверьте её инструкцию.'), ('Кто готовит основание под бак?', 'Готовность и параметры основания подтверждают по проекту и документации поставщика. Аренда крана сама по себе не включает эти работы.'), ('Нужно ли указывать фитинги в заявке?', 'Да, выступающие элементы следует показать на фотографиях и чертеже, чтобы исполнитель учёл их при организации перемещения.')],
[('Достаточно ли сообщить мощность насоса?', 'Нет, требуются модель, масса и документация конкретного агрегата, а также условия извлечения из сооружения.'), ('Кто отключает насос?', 'Подготовку и отключение согласуют с эксплуатирующей либо обслуживающей организацией. Состав обязанностей фиксируют до подачи техники.'), ('Нужна ли схема колодца?', 'Для планирования полезны размеры проёма, препятствия, положение агрегата и возможная стоянка крана. Фотографии дополняют размеры.'), ('Входит ли запуск в аренду?', 'Пуск системы после установки выполняют в согласованном объёме профильные специалисты. Его не следует автоматически считать частью кранового этапа.')],
[('Можно поднять редуктор за рымы двигателя?', 'Инструкция ABB ограничивает рымы массой самого двигателя. Для всей сборки нужна применимая схема её изготовителя.'), ('Какую массу передавать диспетчеру?', 'Массу фактического грузового места с его комплектацией. Значение для отдельного двигателя не описывает всю установку на раме.'), ('Кто перемещает двигатель внутри цеха?', 'Участие принимающей такелажной бригады и границу работ согласуют заранее. Разгрузка у ворот не равна установке на фундамент.'), ('Нужно ли описывать старый двигатель при замене?', 'Да, снятие старого оборудования является отдельным этапом. Для него передают собственные массу, схему и условия подготовки.')],
]
